from research_helpers import *
a=ev('https://www.smartkem.com/wp-content/uploads/2025/08/Smartkem-Technical-Data-Sheets-DIGITAL.pdf','Manufacturer technical catalogue provides six distinct TRUFLEX material codes with ordering information. Container volumes not separately counted.')
b=ev('https://www.sec.gov/Archives/edgar/data/1817760/000110465926040562/smtk-20251231x10k.htm','2025 annual report documents customer ink sales and MiP4 four-MicroLED demonstration package; prototype not assumed mass-produced.')
c=ev('https://ir.smartkem.com/sec-filings/all-sec-filings/content/0001104659-26-108966/tm2625671d2_s3.htm','September 2026 issuer continues TRUFLEX materials operations despite subsidiary liquidation process. Patent transfer does not establish discontinuation of material products.')
products=[]
for code,desc in [('XGI-01-15-02','Organic gate dielectric formulation.'),('XSC-03-06-03','Organic semiconductor ink for thin-film transistor channels.'),('XSL-01-01-03','Base-layer material for organic transistor fabrication.'),('XSL-01-02-01','Protective dielectric formulation for sputter processing.'),('XSL-01-04-03','Passivating film formulation for organic thin-film transistors.'),('XSM-04-04-03','Electrode interface treatment for carrier injection.')]:
 products.append(p('TRUFLEX '+code,desc,a,'commercial',roles=['developer','manufacturer'],typ='product',sector='semiconductors',sub='materials_and_packaging',evidence=[a,c]))
products.append(p('Smartkem MiP4','Four-MicroLED chip-first package demonstrated in smart backlight applications; not inferred to be a commercial display SKU.',b,'development',typ='development_program',sector='semiconductors',sub='materials_and_packaging'))
co=dict(company_id='cmp_073f2db9-daa5-4eab-ad7c-a71eb4f8fc87',products=products,evidence=[a,b,c],status='partial',coverage_note='Six manufacturer-coded TRUFLEX materials and MiP4 demonstrator recorded. TRUFLEX umbrella not duplicated as seventh material. Partial: auxiliary process solvents, additional current formulation codes, advanced packaging custom products and 2026 strategy changes require further review. Display application categories not treated as commercially sold finished panels.')
(out/'batch-0212.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
